import { Emitter, HLJSApi, Language } from "highlight.js";

function throwError(error: Error): never {
  throw error;
}

function unescapeHTML(html: string) {
  return html.replace(
    /&(?:lt|gt|quot|#x27|amp);/g,
    match => "                                   '                                                             @     >    <    \""[match.charCodeAt(1)]);
}

function detectDiffType(diff: string): "normal" | "context" | "unified" {
  let normalScore = 0;
  let contextScore = 0;
  let unifiedScore = 0;

  const regExp = /^(?:([\d<>])|([*!])|(\+\+|[ +-]\S|@)|([ +-] ))/gm;
  while (true) {
    const match = regExp.exec(diff);
    if (!match) break;
    if (match[1]) normalScore++;
    else if (match[2]) contextScore++;
    else if (match[3]) unifiedScore++;
    else if (match[4]) normalScore--;
  }

  if (unifiedScore >= contextScore && unifiedScore >= normalScore)
    return "unified";
  else if (contextScore >= normalScore) return "context";
  else return "normal";
}

type EmitTokensLanguage =
  Omit<Language, "contains">
  & Partial<Pick<Language, "contains">>
  & {
    __emitTokens?: (codeToHighlight: string, emitter: Emitter) => void
  };

export function diffOf(language: string) {
  return (hljs: HLJSApi): Language => {
    const getFileLanguage = (file: string) => {
      const match = file.match(/[^\s\/\\]((?:\.[^\s\/\\]+)+)$/);
      if (match) {
        const extensions = match[1].split(".").slice(1).reverse();
        for (const extension of extensions) {
          if (hljs.getLanguage(extension)) {
            return extension;
          }
        }
      }
      return null;
    }

    function emitTokens(codeToHighlight: string, emitter: Emitter) {
      const diffType = detectDiffType(codeToHighlight);

      let contextSection: "old" | "new" | null = null;
      let oldFileLanguage: string | null = null;
      let newFileLanguage: string | null = null;
      let oldLinesRemaining: number | null = null;
      let newLinesRemaining: number | null = null;

      const codeLines: {
        status: "added" | "changed" | "deleted",
        line: string,
        emit: (highlightedLine: () => void) => void
      }[] = [];

      const added = (
        line: string,
        emit: (highlighedLine: () => void) => void) => {
        codeLines.push({ status: "added", line, emit });
      }

      const changed = (
        line: string,
        emit: (highlighedLine: () => void) => void) => {
        codeLines.push({ status: "changed", line, emit });
      }

      const deleted = (
        line: string,
        emit: (highlighedLine: () => void) => void) => {
        codeLines.push({ status: "deleted", line, emit });
      }

      const parse = (highlighedLine: string, stack: (() => void)[]) => {
        const actions = [...stack];
        const spanRegExp = /<span class="([^"]+)">|<\/span>/g;
        let index = 0;
        while (true) {
          const match = spanRegExp.exec(highlighedLine);
          const chunk = unescapeHTML(highlighedLine.substring(
            index,
            match ? match.index : undefined));
          actions.push(() => {
            emitter.addText(chunk);
          });
          index = spanRegExp.lastIndex;
          if (match) {
            if (match[1]) {
              const action = () => {
                emitter.startScope(match[1].substring(5));
              };
              actions.push(action);
              stack.push(action);
            } else {
              actions.push(() => {
                emitter.endScope();
              });
              stack.pop();
            }
          } else break;
        }
        actions.push(...stack.map(_ => () => emitter.endScope()));
        return () => actions.forEach(action => action());
      }

      const drain = () => {
        const newLinesStack: (() => void)[] = [];
        const highlighedNewLines = hljs.highlight(codeLines
          .filter(line => line.status !== "deleted")
          .map(line => line.line)
          .join("\n"),
          {
            language: newFileLanguage ?? language
          })
          .value
          .split("\n")
          .map(highlighedLine => parse(highlighedLine, newLinesStack));
        if (newLinesStack.length > 0) {
          throwError(Error("Impossible"));
        }
        const oldLinesStack: (() => void)[] = [];
        const highlighedOldLines = hljs.highlight(codeLines
          .filter(line => line.status !== "added")
          .map(line => line.line)
          .join("\n"),
          {
            language: oldFileLanguage ?? language
          })
          .value
          .split("\n")
          .map(highlighedLine => parse(highlighedLine, oldLinesStack));
        if (oldLinesStack.length > 0) {
          throwError(Error("Impossible"));
        }

        for (const { status, emit } of codeLines) {
          let highlightedLine: () => void;
          switch (status) {
            case "added":
              highlightedLine = highlighedNewLines.shift()!;
              break;
            case "changed":
              highlighedOldLines.shift();
              highlightedLine = highlighedNewLines.shift()!;
              break;
            case "deleted":
              highlightedLine = highlighedOldLines.shift()!;
              break;
          }
          emit(highlightedLine);
        }

        codeLines.splice(0, codeLines.length);
      }

      const normalDiffRange = (line: string) => {
        const match = line.match(/^(\d+)(?:(,)(\d+))?([acd])(\d+)(?:(,)(\d+))?([\r\n]*)$/);
        if (match) {
          drain();
          emitter.startScope("number");
          emitter.addText(match[1]);
          emitter.endScope();
          if (match[2]) {
            emitter.startScope("punctuation");
            emitter.addText(match[2]);
            emitter.endScope();
          }
          if (match[3]) {
            emitter.startScope("number");
            emitter.addText(match[3]);
            emitter.endScope();
          }
          emitter.startScope("keyword");
          emitter.addText(match[4]);
          emitter.endScope();
          emitter.startScope("number");
          emitter.addText(match[5]);
          emitter.endScope();
          if (match[6]) {
            emitter.startScope("punctuation");
            emitter.addText(match[6]);
            emitter.endScope();
          }
          if (match[7]) {
            emitter.startScope("number");
            emitter.addText(match[7]);
            emitter.endScope();
          }
          if (match[8]) {
            emitter.addText(match[8]);
          }
          return true;
        } else return false;
      };

      const normalDiffDeleted = (line: string) => {
        const match = line.match(/^(<)( )(.*)([\r\n]*)$/);
        if (match) {
          deleted(match[3], (highlightedLine) => {
            emitter.startScope("operator");
            emitter.addText(match[1]);
            emitter.endScope();
            emitter.addText(match[2]);
            emitter.startScope("deletion");
            highlightedLine();
            emitter.endScope();
            if (match[4]) {
              emitter.addText(match[4]);
            }
          });
          return true;
        } else return false;
      };

      const normalDiffDivider = (line: string) => {
        const match = line.match(/^(---)([\r\n]*)$/);
        if (match) {
          drain();
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          if (match[2]) {
            emitter.addText(match[2]);
          }
          return true;
        } else return false;
      }

      const normalDiffAdded = (line: string) => {
        const match = line.match(/^(>)( )(.*)([\r\n]*)$/);
        if (match) {
          added(match[3], (highlightedLine) => {
            emitter.startScope("operator");
            emitter.addText(match[1]);
            emitter.endScope();
            emitter.addText(match[2]);
            emitter.startScope("addition");
            highlightedLine();
            emitter.endScope();
            if (match[4]) {
              emitter.addText(match[4]);
            }
          });
          return true;
        } else return false;
      };

      const contextDiffOldFile = (line: string) => {
        const match = line.match(/^(\*{3})( )([^\t]+)(\t)(.*)([\r\n]*)$/);
        if (match) {
          contextSection = null;
          oldFileLanguage = getFileLanguage(match[3]);
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("string");
          emitter.addText(match[3]);
          emitter.endScope();
          emitter.addText(match[4]);
          emitter.startScope("number");
          emitter.addText(match[5]);
          emitter.endScope();
          if (match[6]) {
            emitter.addText(match[6]);
          }
          return true;
        } else return false;
      }

      const contextDiffNewFile = (line: string) => {
        const match = line.match(/^(-{3})( )([^\t\r\n]+)(\t)(.*)([\r\n]*)$/);
        if (match) {
          newFileLanguage = getFileLanguage(match[3]);
          contextSection = null;
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("string");
          emitter.addText(match[3]);
          emitter.endScope();
          emitter.addText(match[4]);
          emitter.startScope("number");
          emitter.addText(match[5]);
          emitter.endScope();
          if (match[6]) {
            emitter.addText(match[6]);
          }
          return true;
        } else return false;
      }

      const contextDiffHunkSeparator = (line: string) => {
        const match = line.match(/^(\*{15})([\r\n]*)$/);
        if (match) {
          drain();
          contextSection = null;
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          if (match[2]) {
            emitter.addText(match[2]);
          }
          return true;
        } else return false;
      }

      const contextDiffOldSection = (line: string) => {
        const match = line.match(
          /^(\*{3})( )(\d+)(,)(\d+)( )(\*{4})([\r\n]*)$/);
        if (match) {
          drain();
          contextSection = "old";
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("number");
          emitter.addText(match[3]);
          emitter.endScope();
          emitter.startScope("punctuation")
          emitter.addText(match[4]);
          emitter.endScope();
          emitter.startScope("number");
          emitter.addText(match[5]);
          emitter.endScope();
          emitter.addText(match[6]);
          emitter.startScope("operator");
          emitter.addText(match[7]);
          emitter.endScope();
          if (match[8]) {
            emitter.addText(match[8]);
          }
          return true;
        } else return false;
      }

      const contextDiffNewSection = (line: string) => {
        const match = line.match(
          /^(-{3})( )(\d+)(,)(\d+)( )(-{4})([\r\n]*)$/);
        if (match) {
          drain();
          contextSection = "new";
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("number");
          emitter.addText(match[3]);
          emitter.endScope();
          emitter.startScope("punctuation")
          emitter.addText(match[4]);
          emitter.endScope();
          emitter.startScope("number");
          emitter.addText(match[5]);
          emitter.endScope();
          emitter.addText(match[6]);
          emitter.startScope("operator");
          emitter.addText(match[7]);
          emitter.endScope();
          if (match[8]) {
            emitter.addText(match[8]);
          }
          return true;
        } else return false;
      }

      const contextDiffLine = (line: string) => {
        const match = line.match(/^([ !+-] )(.*)([\r\n]*)$/);
        if (match) {
          const cs = contextSection;
          (cs === "old" ? deleted : added)(match[2], (highlightedLine) => {
            emitter.addText(match[1]);
            let needEndScope = false;
            if (match[1] === "+ "
              || (match[1] === "! "
                && cs === "new")) {
              emitter.startScope("addition");
              needEndScope = true;
            }
            else if (match[1] === "- "
              || (match[1] === "! "
                && cs === "old")) {
              emitter.startScope("deletion");
              needEndScope = true;
            }
            highlightedLine();
            if (needEndScope) emitter.endScope();
            if (match[3]) {
              emitter.addText(match[3]);
            }
          });
          return true;
        } else return false;
      }

      const unifiedDiffOldFile = (line: string) => {
        if (oldLinesRemaining || newLinesRemaining) return false;
        const match =
          line.match(/^(-{3})( )([^\t\r\n]+)(?:(\t)(.*))?([\r\n]*)$/);
        if (match) {
          oldFileLanguage = getFileLanguage(match[3]);
          contextSection = null;
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("string");
          emitter.addText(match[3]);
          emitter.endScope();
          if (match[4]) {
            emitter.addText(match[4]);
          }
          if (match[5]) {
            emitter.startScope("number");
            emitter.addText(match[5]);
            emitter.endScope();
          }
          if (match[6]) {
            emitter.addText(match[6]);
          }
          return true;
        } else return false;
      }

      const unifiedDiffNewFile = (line: string) => {
        if (oldLinesRemaining || newLinesRemaining) return false;
        const match =
          line.match(/^(\+{3})( )([^\t\r\n]+)(?:(\t)(.*))?([\r\n]*)$/);
        if (match) {
          drain();
          newFileLanguage = getFileLanguage(match[3]);
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("string");
          emitter.addText(match[3]);
          emitter.endScope();
          if (match[4]) {
            emitter.addText(match[4]);
          }
          if (match[5]) {
            emitter.startScope("number");
            emitter.addText(match[5]);
            emitter.endScope();
          }
          if (match[6]) {
            emitter.addText(match[6]);
          }
          return true;
        } else return false;
      }

      const unifiedDiffHunkHeader = (line: string) => {
        const match = line.match(
          /^(@{2})( )(-)(\d+)(?:(,)(\d*))?( )(\+)(\d+)(?:(,)(\d*))?( )(@{2})(.*)([\r\n]*)$/);
        if (match) {
          drain();
          oldLinesRemaining = parseInt(match[6] ?? "1");
          newLinesRemaining = parseInt(match[11] ?? "1");
          emitter.startScope("operator");
          emitter.addText(match[1]);
          emitter.endScope();
          emitter.addText(match[2]);
          emitter.startScope("operator");
          emitter.addText(match[3]);
          emitter.endScope();
          emitter.startScope("number");
          emitter.addText(match[4]);
          emitter.endScope();
          if (match[5]) {
            emitter.startScope("punctuation");
            emitter.addText(match[5]);
            emitter.endScope();
          }
          if (match[6]) {
            emitter.startScope("number");
            emitter.addText(match[6]);
            emitter.endScope();
          }
          emitter.addText(match[7]);
          emitter.startScope("operator");
          emitter.addText(match[8]);
          emitter.endScope();
          emitter.startScope("number");
          emitter.addText(match[9]);
          emitter.endScope();
          if (match[10]) {
            emitter.startScope("punctuation");
            emitter.addText(match[10]);
            emitter.endScope();
          }
          if (match[11]) {
            emitter.startScope("number");
            emitter.addText(match[11]);
            emitter.endScope();
          }
          emitter.addText(match[12]);
          emitter.startScope("operator");
          emitter.addText(match[13]);
          emitter.endScope();
          if (match[14]) {
            emitter.startScope("comment");
            emitter.addText(match[14]);
            emitter.endScope();
          }
          if (match[15]) {
            emitter.addText(match[15]);
          }
          return true;
        } else return false;
      }

      const unifiedDiffLine = (line: string) => {
        const match = line.match(/^([ +-])(.*)([\r\n]*)$/);
        if (match) {
          if (match[1] === " "
            && oldLinesRemaining !== 0
            && newLinesRemaining !== 0) {
            if (oldLinesRemaining !== null) oldLinesRemaining--;
            if (newLinesRemaining !== null) newLinesRemaining--;
            changed(match[2], (highlightedLine) => {
              emitter.addText(match[1]);
              highlightedLine();
              if (match[3]) {
                emitter.addText(match[3]);
              }
            });
            return true;
          } else if (match[1] === "+" && newLinesRemaining !== 0) {
            if (newLinesRemaining !== null) newLinesRemaining--;
            added(match[2], (highlightedLine) => {
              emitter.startScope("operator");
              emitter.addText(match[1]);
              emitter.endScope();
              emitter.startScope("addition");
              highlightedLine();
              emitter.endScope();
              if (match[3]) {
                emitter.addText(match[3]);
              }
            });
            return true;
          } else if (match[1] === "-" && oldLinesRemaining !== 0) {
            if (oldLinesRemaining !== null) oldLinesRemaining--;
            deleted(match[2], (highlightedLine) => {
              emitter.startScope("operator");
              emitter.addText(match[1]);
              emitter.endScope();
              emitter.startScope("deletion");
              highlightedLine();
              emitter.endScope();
              if (match[3]) {
                emitter.addText(match[3]);
              }
            });
            return true;
          } else return false;
        } else return false;
      }

      const comment = (line: string) => {
        const match = line.match(/^(.+)([\r\n]*)$/);
        if (match) {
          emitter.startScope("comment");
          emitter.addText(match[1]);
          emitter.endScope();
          if (match[2]) {
            emitter.addText(match[2]);
          }
          return true;
        } else return false;
      }

      const empty = (line: string) => {
        const match = line.match(/^([\r\n]*)$/);
        if (match) {
          if (match[1]) {
            emitter.addText(match[1]);
          }
          return true;
        } else return false;
      }

      try {
        const lineRegExp = /.*(?:\r\n|\n\r|\r|\n)?/g;
        while (true) {
          const line = lineRegExp.exec(codeToHighlight)?.[0]
            ?? throwError(Error("Impossible"));
          switch (diffType) {
            case "normal":
              normalDiffRange(line)
                || normalDiffDeleted(line)
                || normalDiffDivider(line)
                || normalDiffAdded(line)
                || comment(line)
                || empty(line);
              break;
            case "context":
              contextDiffOldFile(line)
                || contextDiffNewFile(line)
                || contextDiffHunkSeparator(line)
                || contextDiffOldSection(line)
                || contextDiffNewSection(line)
                || contextDiffLine(line)
                || comment(line)
                || empty(line);
              break;
            case "unified":
              unifiedDiffOldFile(line)
                || unifiedDiffNewFile(line)
                || unifiedDiffHunkHeader(line)
                || unifiedDiffLine(line)
                || comment(line)
                || empty(line);
              break;
          }
          if (lineRegExp.lastIndex === codeToHighlight.length) break;
        }
        drain();
      } catch (error) {
        console.error(error);
      }
    }

    const result: EmitTokensLanguage = {
      name: "Diff",
      aliases: ["diff", "patch"],
      __emitTokens: emitTokens
    };

    return result as Language;
  }
}

const diff = diffOf("plaintext");
export default diff;
